+							log.Printf("[SCANNER] Event match for library (ID:%s, Path:%s): %s %s", libID, libPath, event.Name, event.Op)
+							
+							// 새 디렉토리가 생성되거나 이동되어 들어오면 감시 목록에 추가
+							if event.Op&(fsnotify.Create|fsnotify.Rename) != 0 {
